// Weekly dependency report. Reads `npm outdated --json` and `npm audit --json`
// output for each folder and prints a Markdown report with what is behind,
// what is vulnerable and the commands to fix it. It never changes anything:
// updates are applied by hand on dev, tested, then released.
//
//   node .github/deps/report.mjs <label>=<outdated.json>,<audit.json> ...
import { readFileSync } from 'node:fs';

function readJson(file) {
  try { return JSON.parse(readFileSync(file, 'utf8') || '{}'); } catch { return {}; }
}

function major(version) {
  const m = /^(\d+)/.exec(String(version || ''));
  return m ? Number(m[1]) : null;
}

export function outdatedRows(outdated) {
  return Object.entries(outdated || {}).map(([name, info]) => {
    const current = info.current || '(not installed)';
    const latest = info.latest || '';
    const wanted = info.wanted || '';
    const isMajor = major(current) !== null && major(latest) !== null && major(latest) > major(current);
    return { name, current, wanted, latest, isMajor };
  }).sort((a, b) => Number(b.isMajor) - Number(a.isMajor) || a.name.localeCompare(b.name));
}

export function auditRows(audit) {
  const vulns = (audit && audit.vulnerabilities) || {};
  const order = { critical: 0, high: 1, moderate: 2, low: 3, info: 4 };
  return Object.entries(vulns).map(([name, v]) => {
    const advisories = (v.via || []).filter((x) => typeof x === 'object' && x.url).map((x) => x.url);
    const fix = v.fixAvailable === true ? 'npm audit fix'
      : (v.fixAvailable && typeof v.fixAvailable === 'object')
        ? `npm install ${v.fixAvailable.name}@${v.fixAvailable.version}${v.fixAvailable.isSemVerMajor ? ' (major)' : ''}`
        : 'no fix yet';
    return { name, severity: v.severity || 'unknown', fix, advisories: [...new Set(advisories)] };
  }).sort((a, b) => (order[a.severity] ?? 9) - (order[b.severity] ?? 9) || a.name.localeCompare(b.name));
}

// Packages deliberately held back, with the reason (.github/deps/held.json).
// npm reports an aliased dependency as "alias:target@range"; match the alias.
export function splitHeld(rows, held = {}) {
  const key = (name) => String(name).split(':')[0];
  return {
    active: rows.filter((r) => !Object.hasOwn(held, key(r.name))),
    held: rows.filter((r) => Object.hasOwn(held, key(r.name))).map((r) => ({ ...r, reason: held[key(r.name)] })),
  };
}

export function renderSection(label, dir, outdated, audit, heldList = {}) {
  const { active: out, held } = splitHeld(outdatedRows(outdated), heldList);
  const vul = auditRows(audit);
  const lines = [`## ${label} (\`${dir}\`)`, ''];
  if (vul.length) {
    lines.push(`### Vulnerabilities (${vul.length})`, '', '| Package | Severity | Fix | Advisory |', '|---|---|---|---|');
    for (const v of vul) lines.push(`| ${v.name} | ${v.severity} | \`${v.fix}\` | ${v.advisories.slice(0, 2).join(' ') || '-'} |`);
    lines.push('');
  } else {
    lines.push('No known vulnerabilities.', '');
  }
  if (out.length) {
    lines.push(`### Outdated (${out.length})`, '', '| Package | Current | Safe update | Latest | |', '|---|---|---|---|---|');
    for (const o of out) lines.push(`| ${o.name} | ${o.current} | ${o.wanted} | ${o.latest} | ${o.isMajor ? 'major: test on dev first' : ''} |`);
    lines.push('');
    const safe = out.filter((o) => !o.isMajor).map((o) => o.name);
    if (safe.length) lines.push('Safe updates (same major version):', '', '```sh', `cd ${dir} && npm update ${safe.join(' ')}`, '```', '');
    const majors = out.filter((o) => o.isMajor).map((o) => `${o.name}@${o.latest}`);
    if (majors.length) lines.push('Major updates (read the release notes, test on dev):', '', '```sh', `cd ${dir} && npm install ${majors.join(' ')}`, '```', '');
  } else {
    lines.push('Everything is up to date.', '');
  }
  if (held.length) {
    lines.push('Held on purpose:', '');
    for (const h of held) lines.push(`- ${String(h.name).split(':')[0]} ${h.current} (latest ${h.latest}): ${h.reason}`);
    lines.push('');
  }
  return lines.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const heldList = readJson(new URL('./held.json', import.meta.url).pathname);
  const parts = ['# Weekly dependency report', '',
    'Generated by `.github/workflows/dependency-report.yml`. Nothing is updated automatically: apply changes on dev, run the tests, then release.', ''];
  for (const arg of process.argv.slice(2)) {
    const [head, files] = arg.split('=');
    const [label, dir] = head.split(':');
    const [outdatedFile, auditFile] = files.split(',');
    parts.push(renderSection(label, dir || '.', readJson(outdatedFile), readJson(auditFile), heldList));
  }
  process.stdout.write(parts.join('\n') + '\n');
}
